files.append('srusdat_dependencies.json')
manifest={}
for n in dict.fromkeys(files):
 b=(DATA/n).read_bytes();j=json.loads(b);manifest[n]={'url':'https://todayindefi.github.io/backing-monitor/data/'+n,'sha256':hashlib.sha256(b).hexdigest(),'bytes':len(b),'as_of':j.get('as_of',j.get('timestamp',j.get('timestamp_utc'))) if isinstance(j,dict) else None}
